#!/bin/bash
# Runs INSIDE a privileged debian:trixie container whose netns owns the hwsim radios
# phy0 (AP), phy1..phy3 (stations). Proves per-device Wi-Fi credentials generated by seg-spike.
# usage: hwsim-inner.sh /out/seg-spike /src/examples/hwsim.json
set -u
BIN=$1; CFG=$2; W=/w; mkdir -p $W/ap $W/log
pass=0; fail=0
ok()  { echo "  PASS  $*"; pass=$((pass+1)); }
bad() { echo "  FAIL  $*"; fail=$((fail+1)); }
X() { ip netns exec "$@"; }

# the four phys arrive in this netns under whatever names the kernel gave them (phyN counts up forever)
PHYS=($(ls /sys/class/ieee80211 | sort -V))
APIF=$(iw dev | awk '/Interface/{print $2; exit}'); ip link set $APIF down; ip link set $APIF name wlan0
for n in 1 2 3; do
  ip netns add sta$n; iw phy ${PHYS[$n]} set netns name sta$n
  old=$(X sta$n iw dev | awk '/Interface/{print $2; exit}'); X sta$n ip link set $old name wlan$n
  X sta$n ip link set wlan$n up
done
ip link set wlan0 up; echo "AP  wlan0: $(cat /sys/class/net/wlan0/address)"
for n in 1 2 3; do echo "STA$n wlan: $(X sta$n cat /sys/class/net/wlan$n/address 2>&1)"; done
echo "hostapd $(hostapd -v 2>&1 | head -1)"; echo "wpa_supplicant $(wpa_supplicant -v 2>&1 | head -1)"

gen() { # name cfg-json  -> $W/ap/<name>/{hostapd.conf,wpa_psk_file}
  mkdir -p $W/ap/$1; $BIN hostapd $2 $W/ap/$1 || { echo "generator failed"; exit 1; }
  sed -i "s|WPA_PSK_FILE_PATH|$W/ap/$1/wpa_psk_file|" $W/ap/$1/hostapd.conf
}
start_ap() { # name
  rm -rf /run/hostapd; mkdir -p /run/hostapd
  hostapd -dd -f $W/log/hostapd-$1.log -B -P $W/ap.pid $W/ap/$1/hostapd.conf >/dev/null 2>&1 || { echo "hostapd did not start"; cat $W/log/hostapd-$1.log | tail; return 1; }
  for i in $(seq 20); do hostapd_cli -p /run/hostapd -i wlan0 status 2>/dev/null | grep -q "state=ENABLED" && return 0; sleep 0.5; done
  echo "hostapd not ENABLED"; return 1
}
stop_ap() { [ -f $W/ap.pid ] && kill $(cat $W/ap.pid) 2>/dev/null; sleep 1; rm -f $W/ap.pid; }
sta_conf() { # n keymgmt secret [id] [bssid-less]
  local n=$1 km=$2 sec=$3 id=${4:-}
  mkdir -p $W/sta$n
  { echo "ctrl_interface=/run/wpa_sta$n"; echo "update_config=0"; [ "$km" = SAE ] && echo "sae_pwe=2"; echo "network={"; echo '  ssid="patronus-seg-lab"'; echo "  key_mgmt=$km"
    if [ "$km" = SAE ]; then echo "  sae_password=\"$sec\""; [ -n "$id" ] && echo "  sae_password_id=\"$id\""; echo "  ieee80211w=2"; else echo "  psk=\"$sec\""; echo "  ieee80211w=1"; fi
    echo "  scan_freq=2437"; echo "}"; } > $W/sta$n/wpa.conf
}
sta_start() { X sta$1 wpa_supplicant -B -i wlan$1 -c $W/sta$1/wpa.conf -f $W/log/sta$1.log -P $W/sta$1/pid > $W/log/sta$1.start 2>&1 || { echo "  (wpa_supplicant sta$1 failed to start:)"; sed "s/^/    /" $W/log/sta$1.start | head -5; }; }
sta_stop() { local p; p=$(cat $W/sta$1/pid 2>/dev/null)
  X sta$1 wpa_cli -p /run/wpa_sta$1 -i wlan$1 terminate >/dev/null 2>&1
  for i in $(seq 20); do [ -n "$p" ] && [ -d /proc/$p ] && sleep 0.3 || break; done
  [ -n "$p" ] && kill -9 $p 2>/dev/null; rm -f $W/sta$1/pid; rm -rf /run/wpa_sta$1; sleep 1; }
sta_state() { X sta$1 wpa_cli -p /run/wpa_sta$1 -i wlan$1 status 2>/dev/null | sed -n 's/^wpa_state=//p'; }
wait_assoc() { for i in $(seq ${2:-16}); do [ "$(sta_state $1)" = COMPLETED ] && return 0; sleep 0.5; done; return 1; }
expect_join() { # n desc
  if wait_assoc $1 20; then ok "$2 -> associated"; else bad "$2 should associate but state=$(sta_state $1)"; fi; }
expect_refused() { # n desc
  sleep 8; local s; s=$(sta_state $1)
  if [ "$s" != COMPLETED ]; then ok "$2 -> refused (state=$s)"; else bad "$2 was admitted"; fi; }
ap_sta_list() { hostapd_cli -p /run/hostapd -i wlan0 list_sta 2>/dev/null | tr '\n' ' '; }

echo; echo "################ WPA2-PSK, per-MAC passphrases (wpa_psk_file) ################"
python3 - $CFG $W/psk.json <<'EOF'
import json,sys
c=json.load(open(sys.argv[1])); 
for d in c["devices"]: d["wifi"].pop("sae_password"); d["wifi"].pop("sae_id")
json.dump(c,open(sys.argv[2],"w"))
EOF
gen psk $W/psk.json
echo "--- generated wpa_psk_file:"; cat $W/ap/psk/wpa_psk_file
echo "--- generated hostapd.conf:"; grep -v '^#' $W/ap/psk/hostapd.conf
start_ap psk && ok "hostapd accepted the generated config and is ENABLED" || bad "hostapd rejected the generated config"
sta_conf 1 WPA-PSK laptop-psk-4f9c2e71; sta_start 1
sta_conf 2 WPA-PSK phone-psk-71be09d3;  sta_start 2
expect_join 1 "laptop (02:..:01:00) with its own PSK"
expect_join 2 "phone  (02:..:02:00) with its own PSK"
echo "  AP station list: $(ap_sta_list)"
sta_conf 3 WPA-PSK laptop-psk-4f9c2e71; sta_start 3
expect_refused 3 "stranger (02:..:03:00, not enrolled) using the laptop's PSK"
sta_stop 3
sta_stop 2; sta_conf 2 WPA-PSK laptop-psk-4f9c2e71; sta_start 2
expect_refused 2 "phone using the LAPTOP's PSK (PSK is bound to the laptop's MAC)"
sta_stop 2; sta_conf 2 WPA-PSK phone-psk-71be09d3; sta_start 2
expect_join 2 "phone back on its own PSK (control)"

echo "--- revoke the phone: re-render, hostapd_cli reload_wpa_psk + deauthenticate (no hostapd restart)"
python3 - $CFG $W/psk-revoked.json <<'EOF'
import json,sys
c=json.load(open(sys.argv[1]))
for d in c["devices"]:
    d["wifi"].pop("sae_password"); d["wifi"].pop("sae_id")
    if d["name"]=="phone": d["revoked"]=True
json.dump(c,open(sys.argv[2],"w"))
EOF
gen psk-rev $W/psk-revoked.json
echo "  revoked psk file now:"; sed 's/^/    /' $W/ap/psk-rev/wpa_psk_file
cp $W/ap/psk-rev/wpa_psk_file $W/ap/psk/wpa_psk_file       # atomic replace in production (write tmp + rename)
hostapd_cli -p /run/hostapd -i wlan0 reload_wpa_psk
hostapd_cli -p /run/hostapd -i wlan0 deauthenticate 02:00:00:00:02:00 >/dev/null
sleep 10
echo "  AP station list: $(ap_sta_list)"
hostapd_cli -p /run/hostapd -i wlan0 sta 02:00:00:00:02:00 2>/dev/null | grep -q "flags=.*AUTHORIZED" && bad "AP still has the revoked phone AUTHORIZED" || ok "AP no longer has the revoked phone AUTHORIZED"
[ "$(sta_state 2)" != COMPLETED ] && ok "revoked phone is disconnected and its old PSK is refused on retry (state=$(sta_state 2))" || bad "revoked phone still associated"
[ "$(sta_state 1)" = COMPLETED ] && ok "laptop unaffected by the reload" || bad "laptop dropped by the reload"
grep -c "4-Way Handshake failed\|WPA: .*PSK\|did not acknowledge\|not authorized" $W/log/hostapd-psk.log | sed 's/^/  hostapd log lines about rejected handshakes: /'
sta_stop 1; sta_stop 2; stop_ap

echo; echo "################ WPA2 enrolment wildcard + revoked device ################"
python3 - $CFG $W/enrol.json <<'EOF'
import json,sys
c=json.load(open(sys.argv[1]))
for d in c["devices"]:
    d["wifi"].pop("sae_password"); d["wifi"].pop("sae_id")
    if d["name"]=="phone": d["revoked"]=True
c["wifi"]["enrol_password"]="enrol-9d1c77a0b4"
json.dump(c,open(sys.argv[2],"w"))
EOF
gen enrol $W/enrol.json; grep -c keyid= $W/ap/enrol/wpa_psk_file | sed 's/^/  psk entries: /'; start_ap enrol
sta_conf 3 WPA-PSK enrol-9d1c77a0b4; sta_start 3
expect_join 3 "unknown device with the enrolment password (lands in quarantine at the nft layer)"
sta_stop 3; sta_conf 2 WPA-PSK phone-psk-71be09d3; sta_start 2
expect_refused 2 "revoked phone with its old personal PSK (enrolment wildcard enabled)"
sta_stop 2; sta_conf 2 WPA-PSK enrol-9d1c77a0b4; sta_start 2
expect_join 2 "revoked phone with the enrolment password (re-enrolment path, quarantined)"
sta_stop 2; stop_ap

echo; echo "################ WPA2 pending enrolment: per-device wildcard PSK + keyid, learn the MAC, bind it ################"
mkdir -p $W/ap/pend
cat > $W/ap/pend/wpa_psk_file <<EOF2
# two devices enrolled by name only: no MAC known yet, one single-use passphrase each
keyid=dev-tv 00:00:00:00:00:00 tv-pending-5c1d9e22
keyid=dev-cam 00:00:00:00:00:00 cam-pending-0a77b3f4
EOF2
grep -v '^wpa_psk_file\|^wpa_key_mgmt\|^sae' $W/ap/psk/hostapd.conf > $W/ap/pend/hostapd.conf
echo "wpa_key_mgmt=WPA-PSK" >> $W/ap/pend/hostapd.conf; echo "wpa_psk_file=$W/ap/pend/wpa_psk_file" >> $W/ap/pend/hostapd.conf
cat > $W/events.sh <<'EOF2'
#!/bin/sh
echo "$2 $3 $4 $5" >> /w/log/events.txt
EOF2
chmod +x $W/events.sh; : > $W/log/events.txt
start_ap pend && ok "hostapd started with wildcard per-device PSKs"
hostapd_cli -p /run/hostapd -i wlan0 -B -a $W/events.sh >/dev/null 2>&1
sleep 1
sta_conf 3 WPA-PSK cam-pending-0a77b3f4; sta_start 3
expect_join 3 "unknown MAC joins with the camera's pending passphrase"
sleep 1
echo "  hostapd event stream (what Patronus' enrolment watcher reads):"; grep -E "AP-STA-CONNECTED" $W/log/events.txt | sed 's/^/    /'
echo "  hostapd_cli sta:"; hostapd_cli -p /run/hostapd -i wlan0 sta 02:00:00:00:03:00 | grep -iE "keyid|flags|wpa_key_mgmt" | sed 's/^/    /'
grep -qE "keyid=dev-cam" $W/log/events.txt && ok "the connect event names the pending device (keyid=dev-cam) together with the MAC" || bad "no keyid in the connect event"
echo "--- bind: rewrite the entry to the learned MAC, reload, the station stays up"
printf 'keyid=dev-tv 00:00:00:00:00:00 tv-pending-5c1d9e22\nkeyid=dev-cam 02:00:00:00:03:00 cam-pending-0a77b3f4\n' > $W/ap/pend/wpa_psk_file
hostapd_cli -p /run/hostapd -i wlan0 reload_wpa_psk >/dev/null; sleep 3
[ "$(sta_state 3)" = COMPLETED ] && ok "the already-associated camera keeps its link across the reload" || bad "camera dropped by reload"
echo "--- the camera's passphrase no longer works from another MAC; the unused tv passphrase still does"
sta_stop 3; sta_stop 2; sta_conf 2 WPA-PSK cam-pending-0a77b3f4; sta_start 2
expect_refused 2 "another MAC with the camera's now-bound passphrase"
sta_stop 2; sta_conf 2 WPA-PSK tv-pending-5c1d9e22; sta_start 2
expect_join 2 "another unknown MAC with the tv's still-pending passphrase"
sta_stop 2; sta_stop 3; stop_ap

echo; echo "################ WPA3-SAE, per-MAC passwords with identifiers ################"
python3 - $CFG $W/sae.json <<'EOF'
import json,sys
c=json.load(open(sys.argv[1]))
for d in c["devices"]: d["wifi"].pop("psk")
json.dump(c,open(sys.argv[2],"w"))
EOF
gen sae $W/sae.json
echo "--- generated SAE lines:"; grep '^sae_password' $W/ap/sae/hostapd.conf | sed 's/^/    /'
start_ap sae && ok "hostapd accepted the generated SAE config" || bad "hostapd rejected the SAE config"
sta_conf 1 SAE laptop-sae-8d31b0aa laptop; sta_start 1
sta_conf 2 SAE phone-sae-c2a7716e phone;   sta_start 2
expect_join 1 "laptop with its SAE password + identifier 'laptop'"
expect_join 2 "phone with its SAE password + identifier 'phone'"
sta_conf 3 SAE laptop-sae-8d31b0aa laptop; sta_start 3
expect_refused 3 "stranger MAC using the laptop's SAE password+id"
sta_stop 3
sta_stop 2; sta_conf 2 SAE laptop-sae-8d31b0aa laptop; sta_start 2
expect_refused 2 "phone using the laptop's SAE password+id"
sta_stop 2; sta_conf 2 SAE phone-sae-c2a7716e ""; sta_start 2
expect_refused 2 "phone with the right SAE password but WITHOUT the identifier"
sta_stop 2; sta_conf 2 SAE phone-sae-c2a7716e phone; sta_start 2
expect_join 2 "phone back with password+id (control)"

echo "--- revoke the phone's SAE password"
python3 - $CFG $W/sae-revoked.json <<'EOF'
import json,sys
c=json.load(open(sys.argv[1]))
for d in c["devices"]:
    d["wifi"].pop("psk")
    if d["name"]=="phone": d["revoked"]=True
json.dump(c,open(sys.argv[2],"w"))
EOF
gen sae-rev $W/sae-revoked.json
echo "  (a) hostapd_cli reload_wpa_psk only (does it re-read sae_password?)"
cp $W/ap/sae-rev/hostapd.conf $W/ap/sae/hostapd.conf; sed -i "s|WPA_PSK_FILE_PATH|$W/ap/sae/wpa_psk_file|" $W/ap/sae/hostapd.conf
hostapd_cli -p /run/hostapd -i wlan0 reload_wpa_psk >/dev/null
hostapd_cli -p /run/hostapd -i wlan0 deauthenticate 02:00:00:00:02:00 >/dev/null; sleep 10
echo "     phone state after reload_wpa_psk + deauth: $(sta_state 2)   (COMPLETED = SAE password list was NOT reloaded)"
echo "  (b) hostapd_cli reload (re-read hostapd.conf), then deauthenticate the phone"
hostapd_cli -p /run/hostapd -i wlan0 reload 2>&1 | head -2
sleep 3; [ "$(sta_state 1)" = COMPLETED ] && echo "     laptop kept its association across the reload" || echo "     laptop was dropped by the reload (state=$(sta_state 1)); waiting for it to reconnect"
hostapd_cli -p /run/hostapd -i wlan0 deauthenticate 02:00:00:00:02:00 >/dev/null
sleep 10
echo "     phone state after reload: $(sta_state 2); laptop: $(sta_state 1)"
echo "     AP station list: $(ap_sta_list)"
if [ "$(sta_state 2)" != COMPLETED ]; then ok "revoked phone refused after the SAE reload"; else
  echo "  (c) full hostapd restart"; stop_ap; start_ap sae; sleep 12; echo "     phone: $(sta_state 2) laptop: $(sta_state 1)"
  [ "$(sta_state 2)" != COMPLETED ] && ok "revoked phone refused after a hostapd restart (SAE needs restart/reload)" || bad "revoked phone still admitted"; fi
sta_stop 1; sta_stop 2; stop_ap
echo; echo "RESULT: $pass passed, $fail failed"
[ $fail -eq 0 ]
